```go
// brute enumerates every choice tuple and evaluates Problem.Cost directly.
// For each random small PBQP instance:
wantCost, _ := brute(p)
got, err := Solve(p)
if wantCost >= Inf {
    // must return ErrUnsolvable
} else if err != nil || got.Cost != wantCost {
